\title{Unbounded Hausdorff Dimension in Sequence Hilbert Space:\\Embedding, Obstruction, and Finite-Cover Theorems}
\author{Aristotle}
\date{19 July 2026}
\begin{document}
\maketitle

\begin{abstract}
We give a self-contained metric interpretation of geometry beyond every finite dimension. Hausdorff dimension is an extended nonnegative real invariant, so it cannot literally take the cardinal value $\aleph_1$; the appropriate extremal value is $\infty$. We prove that the real sequence Hilbert space $\ell^2$ has infinite Hausdorff dimension by constructing, for every $n$, an isometric coordinate inclusion of $\R^n$ into $\ell^2$. A space of infinite Hausdorff dimension admits no antilipschitz map into a finite-dimensional real normed space and cannot be covered by finitely many subsets of finite Hausdorff dimension. Conversely, $\ell^2$ is separable and embeds topologically in the Hilbert cube $[0,1]^{\N}$. These results distinguish metric fidelity from topological representation and give the metric obstruction underlying the absence of finite triangulations.
\end{abstract}

\section{Introduction}
Finite-dimensional Euclidean geometry organizes spaces by coordinate count. Hausdorff dimension instead measures the rate at which increasingly fine covers proliferate. It agrees with coordinate dimension on $\R^n$, detects nonintegral fractal dimensions, and permits the value $\infty$.

The phrase ``Hausdorff dimension $\aleph_1$'' conflates two invariants. The cardinal $\aleph_1$ belongs to cardinal arithmetic, whereas Hausdorff dimension takes values in $[0,\infty]$. No continuum hypothesis identifies these codomains. The faithful meaning of dimension beyond every finite value is therefore infinite Hausdorff dimension.

Our model is
\[
\ell^2=\left\{x=(x_j)_{j\ge0}:x_j\in\R,\ \sum_{j=0}^{\infty}|x_j|^2<\infty\right\},
\qquad
\|x\|_2=\left(\sum_{j=0}^{\infty}|x_j|^2\right)^{1/2}.
\]
We establish four complementary facts: $\dimH(\ell^2)=\infty$; no antilipschitz map sends it into a finite-dimensional normed space; every $\R^n$ embeds isometrically into it; and it is separable and topologically embeddable in the Hilbert cube.

\section{Preliminaries}
\begin{definition}[Hausdorff measure and dimension]
For $A$ in a metric space, $s\ge0$, and $\delta>0$, set
\[
\mathcal H^s_\delta(A)=\inf\left\{\sum_i(\diam U_i)^s:A\subseteq\bigcup_iU_i,\ \diam U_i\le\delta\right\}.
\]
The $s$-dimensional Hausdorff measure is $\mathcal H^s(A)=\lim_{\delta\downarrow0}\mathcal H^s_\delta(A)$, and
\[
\dimH(A)=\inf\{s\ge0:\mathcal H^s(A)=0\},
\]
with value $\infty$ if this set is empty.
\end{definition}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $A\subseteq B$, then $\dimH(A)\le\dimH(B)$.
\end{lemma}
\begin{proof}
Every cover of $B$ covers $A$, so $\mathcal H^s_\delta(A)\le\mathcal H^s_\delta(B)$. Passing to the limit and then to critical exponents proves the claim.
\end{proof}

\begin{lemma}[Finite unions]\label{lem:union}
For finitely many sets $A_1,\dots,A_m$,
\[
\dimH\left(\bigcup_{i=1}^m A_i\right)=\max_{1\le i\le m}\dimH(A_i).
\]
\end{lemma}
\begin{proof}
Monotonicity gives one inequality. If $s$ exceeds every $\dimH(A_i)$, then $\mathcal H^s(A_i)=0$ for all $i$. Finite subadditivity makes the measure of the union zero, yielding the reverse inequality.
\end{proof}

\begin{lemma}[Finite-dimensional spaces]\label{lem:finite}
If $E$ is an $m$-dimensional real normed vector space, then $\dimH(E)=m$. Hence every $A\subseteq E$ has $\dimH(A)\le m$.
\end{lemma}
\begin{proof}
A linear isomorphism $E\cong\R^m$ is bi-Lipschitz because all norms in finite dimension are equivalent. Hausdorff dimension is invariant under bi-Lipschitz maps, and $\dimH(\R^m)=m$. Apply Lemma~\ref{lem:mono} to subsets.
\end{proof}

\begin{definition}[Antilipschitz map]
A map $f:(X,d_X)\to(Y,d_Y)$ is $K$-antilipschitz if $K>0$ and
\[
d_X(x,x')\le Kd_Y(f(x),f(x'))
\]
for all $x,x'$. Isometries and bi-Lipschitz embeddings are antilipschitz.
\end{definition}

\begin{lemma}[Dimension cannot decrease]\label{lem:anti}
If $f:X\to Y$ is antilipschitz and $A\subseteq X$, then
\[
\dimH(A)\le\dimH(f(A)).
\]
\end{lemma}
\begin{proof}
The lower distance bound makes $f$ injective, and the inverse $f(A)\to A$ is Lipschitz. Since Lipschitz maps do not increase Hausdorff dimension, applying this fact to the inverse proves the inequality.
\end{proof}

\section{Finite-dimensional obstruction}
\begin{theorem}[Finite-Dimensional Obstruction]\label{thm:obstruction}
If $\dimH(S)=\infty$, then no antilipschitz map sends $S$ into a finite-dimensional real normed space. In particular, $S$ admits no isometric or bi-Lipschitz embedding into any $\R^m$.
\end{theorem}
\begin{proof}
If $f:S\to E$ were antilipschitz and $\dim E=m<\infty$, then Lemmas~\ref{lem:anti}, \ref{lem:mono}, and \ref{lem:finite} would give
\[
\infty=\dimH(S)\le\dimH(f(S))\le\dimH(E)=m,
\]
an impossibility.
\end{proof}

\begin{theorem}[Strict Dimension Ladder]\label{thm:strict}
If $E$ is a finite-dimensional real normed space and $\dim E<n$, no antilipschitz map $\R^n\to E$ exists.
\end{theorem}
\begin{proof}
Such a map would imply
\[
n=\dimH(\R^n)\le\dimH(E)=\dim E<n,
\]
by Lemmas~\ref{lem:anti} and \ref{lem:finite}.
\end{proof}

\section{Every finite stage inside $\ell^2$}
For $n\in\N$, define
\[
J_n:\R^n\to\ell^2,\qquad
J_n(x_0,\dots,x_{n-1})=(x_0,\dots,x_{n-1},0,0,\dots).
\]
\begin{lemma}[Norm preservation]\label{lem:norm}
For every $x\in\R^n$, $\|J_nx\|_2=\|x\|_2$.
\end{lemma}
\begin{proof}
Only the first $n$ coordinates are nonzero, and therefore
\[
\|J_nx\|_2^2=\sum_{j=0}^{\infty}|(J_nx)_j|^2
=\sum_{j=0}^{n-1}|x_j|^2=\|x\|_2^2.
\]
Taking nonnegative square roots proves the claim.
\end{proof}

\begin{theorem}[Universal Finite-Stage Isometry]\label{thm:isometry}
For every $n$, $J_n$ is an isometric embedding of $\R^n$ into $\ell^2$.
\end{theorem}
\begin{proof}
Linearity and Lemma~\ref{lem:norm} yield
\[
\|J_nx-J_ny\|_2=\|J_n(x-y)\|_2=\|x-y\|_2.
\]
\end{proof}

\begin{theorem}[Infinite Hausdorff dimension]\label{thm:infinite}
The sequence Hilbert space has $\dimH(\ell^2)=\infty$.
\end{theorem}
\begin{proof}
For each $n$, Theorem~\ref{thm:isometry} provides a subset $J_n(\R^n)$ of Hausdorff dimension $n$. Hence
\[
n=\dimH(J_n(\R^n))\le\dimH(\ell^2)
\]
for every $n$. The only extended nonnegative real dominating all natural numbers is $\infty$.
\end{proof}

\begin{theorem}[Infinite-Dimensional Hilbert Geometry]
There exist a separable Hilbert space $H$ and $S\subseteq H$ such that $\dimH(S)=\infty$, no antilipschitz map sends $S$ into a finite-dimensional real normed space, and $H$ contains an isometric copy of $\R^n$ for every $n$. One may take $H=S=\ell^2$.
\end{theorem}
\begin{proof}
Use Theorems~\ref{thm:infinite}, \ref{thm:obstruction}, and \ref{thm:isometry}. Separability follows below.
\end{proof}

\section{Separability and the Hilbert cube}
Let $D$ consist of finitely supported sequences with rational entries. It is countable, being a countable union of copies of $\mathbb Q^N$.
\begin{lemma}[Separability]\label{lem:separable}
The set $D$ is dense in $\ell^2$.
\end{lemma}
\begin{proof}
Given $x\in\ell^2$ and $\varepsilon>0$, choose $N$ so that the squared tail after $N$ is less than $\varepsilon^2/4$. Approximate the first $N$ coordinates by rationals with total squared error below $\varepsilon^2/4$, and set later coordinates to zero. The resulting member of $D$ is within $\varepsilon$ of $x$.
\end{proof}

The Hilbert cube is $Q=[0,1]^{\N}$ with the product topology, metrized for example by
\[
d_Q(u,v)=\sum_{j=0}^{\infty}2^{-j-1}|u_j-v_j|.
\]
Enumerate a dense subset as $q_0,q_1,\dots$ and put $\rho(t)=t/(1+t)$. Define
\[
\Phi:\ell^2\to Q,\qquad \Phi(x)_j=\rho(\|x-q_j\|_2).
\]

\begin{theorem}[Hilbert-Cube Embedding]\label{thm:cube}
The map $\Phi$ is a topological embedding of $\ell^2$ into $Q$.
\end{theorem}
\begin{proof}
Every coordinate is continuous, so $\Phi$ is continuous. If $x\ne y$, put $r=\|x-y\|_2$ and choose $q_j$ with $\|x-q_j\|_2<r/3$. Then $\|y-q_j\|_2>2r/3$, so the $j$th coordinates differ and $\Phi$ is injective.

Suppose $\Phi(x_k)\to\Phi(x)$ coordinatewise. Given $\varepsilon>0$, choose $q_j$ with $\|x-q_j\|_2<\varepsilon/3$. Since $\rho$ is a homeomorphism onto $[0,1)$, convergence of the $j$th coordinate implies $\|x_k-q_j\|_2\to\|x-q_j\|_2$. For large $k$ this distance is less than $2\varepsilon/3$, and the triangle inequality gives $\|x_k-x\|_2<\varepsilon$. Thus the inverse on the image is continuous.
\end{proof}

\begin{remark}
Theorem~\ref{thm:cube} is topological, not bi-Lipschitz. It does not conflict with Theorem~\ref{thm:obstruction}: the Hilbert cube has countably many coordinates, and no uniform lower metric bound is asserted.
\end{remark}

\section{Finite-cover and triangulation obstructions}
\begin{theorem}[No Finite Finite-Dimensional Cover]\label{thm:cover}
If $\dimH(S)=\infty$, there are no finite-dimensional subsets $A_1,\dots,A_m$ of finite Hausdorff dimension satisfying $S\subseteq\bigcup_{i=1}^mA_i$.
\end{theorem}
\begin{proof}
Lemmas~\ref{lem:mono} and \ref{lem:union} imply
\[
\infty=\dimH(S)\le\dimH\left(\bigcup_{i=1}^mA_i\right)
=\max_i\dimH(A_i),
\]
but the maximum of finitely many finite values is finite.
\end{proof}

\begin{corollary}[Metric obstruction to finite triangulation]
Suppose a proposed finite triangulation of a metric space $S$ realizes it as the union of finitely many simplex images, each of finite Hausdorff dimension---for instance, each realization map is Lipschitz from a finite-dimensional Euclidean simplex. If $\dimH(S)=\infty$, no such triangulation exists.
\end{corollary}
\begin{proof}
The simplex images would form a cover forbidden by Theorem~\ref{thm:cover}.
\end{proof}

\section{Algorithms and numerical illustrations}
The coordinate isometry is computed by appending zeros. For vectors $x,y\in\R^n$ displayed in $\R^N$ with $N\ge n$,
\[
\sum_{j=0}^{N-1}(J_n(x)_j-J_n(y)_j)^2
=\sum_{j=0}^{n-1}(x_j-y_j)^2.
\]
Materializing the output costs $O(N)$ time and storage; checking the distance identity directly costs $O(n)$ time and constant auxiliary space.

A finite approximation to the Hilbert-cube map chooses landmarks $q_0,\dots,q_{M-1}$ in an $N$-coordinate truncation and computes
\[
x\longmapsto\left(\frac{\|x-q_j\|_2}{1+\|x-q_j\|_2}\right)_{j=0}^{M-1}.
\]
Direct evaluation costs $O(MN)$ time and $O(M)$ output storage. Increasing $M$ enriches the address but no finite experiment proves the infinite theorem.

Finally, the strict dimension diagnostic compares $n$ and $m$. If $m<n$, Theorem~\ref{thm:strict} certifies in constant time that global antilipschitz control is impossible. A non-obstructed pair does not automatically provide a construction.

\section{Consequences and boundaries}
The closed unit ball $B\subset\ell^2$ also has infinite Hausdorff dimension. Indeed, the restriction of $J_n$ embeds the Euclidean unit ball in $\R^n$ isometrically into $B$, forcing $\dimH(B)\ge n$ for every $n$. Thus infinite dimension is small-scale complexity, not merely unbounded diameter.

The finite restriction in Theorem~\ref{thm:cover} is essential. For countable unions,
\[
\dimH\left(\bigcup_{i=0}^{\infty}A_i\right)=\sup_i\dimH(A_i).
\]
The finitely supported sequences form a countable union of the stages $J_n(\R^n)$ and already have infinite Hausdorff dimension because their dimensions are unbounded.

The obstruction theorem is metric. It excludes isometric and bi-Lipschitz embeddings, but an unconditional topological non-embedding theorem requires topological dimension theory. Likewise, the triangulation corollary assumes that simplex images have finite Hausdorff dimension in the chosen metric. These qualifications prevent the metric results from being overstated.

\section{Applications}
In dimensionality reduction, a source containing Euclidean pieces of arbitrarily large dimension cannot be compressed into a fixed $\R^m$ while preserving every distance from below by one uniform factor. Practical methods must restrict the dataset, accept distortion, select scales, or let target dimension grow.

Finite-energy signals naturally inhabit $\ell^2$. Truncation to the first $n$ coefficients gives an exact finite-dimensional stage, and all stages coexist isometrically. Yet no one truncation captures every direction in the full space.

The Hilbert-cube embedding separates topological representation from metric fidelity. Countably many bounded distance measurements distinguish all points and recover convergence, while finitely many Euclidean coordinates cannot uniformly preserve the metric.

\section{Discussion and future work}
Cardinality, manifold dimension, vector-space dimension, and Hausdorff dimension answer different questions. The present construction concerns the last two. It needs no continuum hypothesis and does not make $\ell^2$ a two-dimensional surface or a manifold of ordinal dimension.

Natural extensions include an abstract theory of finite topological simplicial complexes with metrically controlled realizations; distortion estimates for explicit Hilbert-cube metrics; compact weighted cubes inside $\ell^2$ with infinite Hausdorff dimension; separate ordinal-valued inductive dimensions; and precise Hilbert or Fr\'echet manifold categories. A purely topological finite-dimensional non-embedding theorem would require covering or cohomological dimension rather than Hausdorff dimension alone.

\section{Conclusion}
The sequence Hilbert space supplies a concrete geometry beyond every finite Hausdorff dimension. Exact copies of all $\R^n$ force $\dimH(\ell^2)=\infty$. This prohibits distance-faithful embeddings into finite-dimensional normed spaces and finite covers by finite-dimensional metric pieces. Nevertheless, separability gives a topological embedding into the Hilbert cube. Unlimited metric dimension and countable topological accessibility are therefore compatible, while global finite-dimensional metric compression remains impossible.

\end{document}

