from __future__ import annotations
from typing import Sequence

def coordinate_padding_isometry(x: Sequence[float], target_dimension: int) -> list[float]:
    if target_dimension < len(x):
        raise ValueError("target_dimension must be at least len(x)")
    return [float(a) for a in x] + [0.0] * (target_dimension - len(x))

from __future__ import annotations
import math
from typing import Sequence

def hilbert_cube_coordinates(x: Sequence[float], landmarks: Sequence[Sequence[float]]) -> list[float]:
    output: list[float] = []
    for q in landmarks:
        if len(q) != len(x): raise ValueError("dimension mismatch")
        d = math.sqrt(sum((a-b)**2 for a, b in zip(x, q)))
        output.append(d / (1.0 + d))
    return output

from __future__ import annotations
from typing import Sequence

def finite_rational_approximation(x: Sequence[float], cutoff: int, digits: int) -> list[float]:
    if not 0 <= cutoff <= len(x): raise ValueError("invalid cutoff")
    return [round(float(a), digits) for a in x[:cutoff]] + [0.0] * (len(x)-cutoff)

